// Cloudflare Pages Function: the Blades Premium price in the visitor's currency (GET /api/price).
// The country is the one Cloudflare's edge sees the request come from (request.cf.country). Nothing is logged,
// stored or set as a cookie. A country outside the App Store's 175, or one Cloudflare can't place, gets the euro.
// Prices: Blades Premium Monthly in App Store Connect (what the customer pays, tax included), 29 Oct 2026.
// Generated by build_fn.py; 'USD+' is the 3.99 level some USD storefronts have.
const PRICE = {"EUR":["2.99","€{n}"],"USD":["2.99","${n}"],"USD+":["3.99","${n}"],"GBP":["2.99","£{n}"],"SEK":["39","{n} kr"],"NOK":["39","{n} kr"],"DKK":["29","{n} kr"],"CHF":["3.00","CHF {n}"],"PLN":["14,99","{n} zł"],"CZK":["79","{n} Kč"],"HUF":["1 490","{n} Ft"],"RON":["14,99","{n} lei"],"TRY":["149,99","₺{n}"],"RUB":["249","{n} ₽"],"KZT":["1 790","{n} ₸"],"CAD":["3.99","${n}"],"AUD":["4.99","${n}"],"NZD":["4.99","${n}"],"JPY":["500","¥{n}"],"KRW":["4,400","₩{n}"],"CNY":["22","¥{n}"],"HKD":["22","HK${n}"],"TWD":["90","NT${n}"],"SGD":["3.98","S${n}"],"MYR":["14.90","RM {n}"],"THB":["99","฿{n}"],"IDR":["59.000","Rp {n}"],"PHP":["199","₱{n}"],"VND":["99.000","{n} ₫"],"INR":["299","₹{n}"],"PKR":["900","Rs {n}"],"AED":["12.99","AED {n}"],"SAR":["12.99","SAR {n}"],"QAR":["9.99","QAR {n}"],"ILS":["9.90","₪{n}"],"EGP":["149.99","EGP {n}"],"ZAR":["59.99","R{n}"],"NGN":["4,900","₦{n}"],"TZS":["9,900","TSh {n}"],"BRL":["19,90","R$ {n}"],"MXN":["69","${n}"],"CLP":["2.990","${n}"],"COP":["14.900","${n}"],"PEN":["12.90","S/ {n}"]};
const COUNTRY = {"AE":"AED","AF":"USD","AG":"USD","AI":"USD","AL":"USD+","AM":"USD+","AO":"USD","AR":"USD","AT":"EUR","AU":"AUD","AZ":"USD+","BA":"EUR","BB":"USD+","BE":"EUR","BF":"USD","BG":"EUR","BH":"USD","BJ":"USD+","BM":"USD","BN":"USD","BO":"USD","BR":"BRL","BS":"USD","BT":"USD","BW":"USD","BY":"USD+","BZ":"USD","CA":"CAD","CD":"USD","CG":"USD+","CH":"CHF","CI":"USD+","CL":"CLP","CM":"USD+","CN":"CNY","CO":"COP","CR":"USD","CV":"USD","CY":"EUR","CZ":"CZK","DE":"EUR","DK":"DKK","DM":"USD","DO":"USD","DZ":"USD","EC":"USD","EE":"EUR","EG":"EGP","ES":"EUR","FI":"EUR","FJ":"USD","FM":"USD","FR":"EUR","GA":"USD","GB":"GBP","GD":"USD","GE":"USD+","GH":"USD+","GM":"USD","GR":"EUR","GT":"USD","GW":"USD","GY":"USD","HK":"HKD","HN":"USD","HR":"EUR","HU":"HUF","ID":"IDR","IE":"EUR","IL":"ILS","IN":"INR","IQ":"USD","IS":"USD+","IT":"EUR","JM":"USD","JO":"USD","JP":"JPY","KE":"USD+","KG":"USD","KH":"USD","KN":"USD","KR":"KRW","KW":"USD","KY":"USD","KZ":"KZT","LA":"USD","LB":"USD","LC":"USD","LK":"USD","LR":"USD","LT":"EUR","LU":"EUR","LV":"EUR","LY":"USD","MA":"USD+","MD":"USD+","ME":"EUR","MG":"USD","MK":"USD","ML":"USD","MM":"USD","MN":"USD","MO":"USD","MR":"USD","MS":"USD","MT":"EUR","MU":"USD+","MV":"USD","MW":"USD","MX":"MXN","MY":"MYR","MZ":"USD","NA":"USD","NE":"USD","NG":"NGN","NI":"USD","NL":"EUR","NO":"NOK","NP":"USD+","NR":"USD","NZ":"NZD","OM":"USD","PA":"USD","PE":"PEN","PG":"USD","PH":"PHP","PK":"PKR","PL":"PLN","PT":"EUR","PW":"USD","PY":"USD","QA":"QAR","RO":"RON","RS":"EUR","RU":"RUB","RW":"USD","SA":"SAR","SB":"USD","SC":"USD","SE":"SEK","SG":"SGD","SI":"EUR","SK":"EUR","SL":"USD","SN":"USD+","SR":"USD","ST":"USD","SV":"USD","SZ":"USD","TC":"USD","TD":"USD","TH":"THB","TJ":"USD","TM":"USD","TN":"USD","TO":"USD","TR":"TRY","TT":"USD","TW":"TWD","TZ":"TZS","UA":"USD+","UG":"USD+","US":"USD","UY":"USD","UZ":"USD","VC":"USD","VE":"USD","VG":"USD","VN":"VND","VU":"USD","XK":"EUR","YE":"USD","ZA":"ZAR","ZM":"USD+","ZW":"USD+"};

export function onRequestGet({ request }) {
  const country = (request.cf && request.cf.country) || null;
  const known = !!(country && COUNTRY[country]);
  const currency = known ? COUNTRY[country] : 'EUR';
  const [n, fmt] = PRICE[currency];
  const body = {
    country,
    currency: currency.replace('+', ''),
    local: known,
    price: fmt.replace('{n}', n),
    free: fmt.replace('{n}', '0'),
  };
  return new Response(JSON.stringify(body), {
    headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'private, max-age=3600' },
  });
}
